function applyStartupRecoveryFromUrl() {
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get("reset") !== "1" && params.get("safe") !== "1") {
      return;
    }

    Object.keys(localStorage)
      .filter((key) => key.startsWith("alibooks-") && key !== "alibooks-token" && key !== "alibooks-email" && key !== "alibooks-language")
      .forEach((key) => localStorage.removeItem(key));
    localStorage.setItem("alibooks-active-view", "overview");
    localStorage.removeItem("alibooks-render-recovery-attempted");
    window.history.replaceState({}, "", window.location.pathname);
  } catch {
    // Continue with normal startup if storage or history is blocked.
  }
}

applyStartupRecoveryFromUrl();

function decodeJwtPayload(token) {
  try {
    const payloadPart = String(token || "").split(".")[1];
    if (!payloadPart) {
      return null;
    }

    const base64 = payloadPart.replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64.padEnd(base64.length + ((4 - (base64.length % 4)) % 4), "=");
    return JSON.parse(window.atob(padded));
  } catch {
    return null;
  }
}

function jwtExpiresAt(token) {
  const payload = decodeJwtPayload(token);
  const expiresAt = Number(payload?.exp || 0);
  return expiresAt > 0 ? expiresAt * 1000 : 0;
}

function jwtIsExpired(token, clockSkewSeconds = 10) {
  const expiresAt = jwtExpiresAt(token);
  return !expiresAt || Date.now() >= expiresAt - (clockSkewSeconds * 1000);
}

function readStoredSessionToken() {
  const storedToken = localStorage.getItem("alibooks-token") || "";
  if (!storedToken || !jwtIsExpired(storedToken, 0)) {
    return storedToken;
  }

  localStorage.removeItem("alibooks-token");
  localStorage.removeItem("alibooks-email");
  localStorage.setItem("alibooks-session-expired", "1");
  return "";
}

