function authErrorMessage(data, fallback, language) {
  const message = apiErrorMessage(data, fallback);
  const normalized = String(message || "").toLowerCase();

  if (language !== "sv") {
    return message;
  }

  if (normalized.includes("too many failed login attempts")) {
    return "For manga felaktiga inloggningsforsok. Vanta en stund och forsok igen.";
  }

  if (normalized.includes("invalid email or password")) {
    return "Fel e-postadress eller losenord.";
  }

  if (normalized.includes("valid email and password with at least 8 characters")) {
    return "Ange en giltig e-postadress och ett losenord med minst 8 tecken.";
  }

  if (normalized.includes("user already exists")) {
    return "Det finns redan ett konto med den e-postadressen.";
  }

  return message;
}

function extractPeriodLockProof(message) {
  const text = String(message || "");
  const fingerprintMatch = text.match(/Period fingerprint:\s*([0-9A-F]{64})/i);
  const chainHashMatch = text.match(/Final chain hash:\s*([0-9A-F]{64})/i);

  return {
    periodFingerprint: fingerprintMatch ? fingerprintMatch[1].toUpperCase() : "",
    finalChainHash: chainHashMatch ? chainHashMatch[1].toUpperCase() : ""
  };
}

