function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function normalizeNameValue(value) {
  return value
    .toLowerCase()
    .replaceAll("\u00e5", "a")
    .replaceAll("\u00e4", "a")
    .replaceAll("\u00f6", "o")
    .replaceAll("\u00e5", "a")
    .replaceAll("\u00e4", "a")
    .replaceAll("\u00f6", "o")
    .replaceAll("å", "a")
    .replaceAll("ä", "a")
    .replaceAll("ö", "o")
    .replace(/[^a-z0-9\s]/g, " ");
}

function stableAuditFingerprint(value) {
  const text = String(value ?? "");
  let hash = 2166136261;

  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0).toString(16).padStart(8, "0").toUpperCase();
}

function canonicalizeForHash(value) {
  if (Array.isArray(value)) {
    return value.map((item) => canonicalizeForHash(item));
  }

  if (value && typeof value === "object") {
    return Object.keys(value)
      .sort()
      .reduce((result, key) => {
        result[key] = canonicalizeForHash(value[key]);
        return result;
      }, {});
  }

  return value;
}

function stableJsonForHash(value) {
  return JSON.stringify(canonicalizeForHash(value));
}

async function sha256Hex(value) {
  const cryptoApi = globalThis.crypto || (typeof window !== "undefined" ? window.crypto : null);
  if (!cryptoApi?.subtle) {
    throw new Error("SHA-256 is not available in this browser.");
  }

  const bytes = new TextEncoder().encode(String(value ?? ""));
  const hashBuffer = await cryptoApi.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(hashBuffer))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("")
    .toUpperCase();
}

function backupControlBasis(backup) {
  const summary = backup?.summary || {};
  const auditProof = backup?.integrityProofs?.auditTrail || {};
  const bookkeepingProof = backup?.integrityProofs?.bookkeeping || {};

  return {
    app: backup?.app || "",
    version: backup?.version || "",
    exportedAt: backup?.exportedAt || "",
    period: backup?.period || {},
    counts: {
      customers: summary.customers || 0,
      invoices: summary.invoices || 0,
      expenses: summary.expenses || 0,
      journalEntries: summary.journalEntries || 0,
      auditEvents: summary.auditEvents || 0,
      backendAuditEvents: summary.backendAuditEvents || 0,
      auditIntegrityEvents: summary.auditIntegrityEvents || 0
    },
    integrityProofs: {
      auditTrail: {
        eventCount: auditProof.eventCount || 0,
        firstChainHash: auditProof.firstChainHash || "",
        finalChainHash: auditProof.finalChainHash || "",
        auditFingerprint: auditProof.auditFingerprint || ""
      },
      bookkeeping: {
        entryCount: bookkeepingProof.entryCount || 0,
        voucherCount: bookkeepingProof.voucherCount || 0,
        finalChainHash: bookkeepingProof.finalChainHash || "",
        periodFingerprint: bookkeepingProof.periodFingerprint || ""
      }
    }
  };
}

function backupControlFingerprint(backup) {
  return stableAuditFingerprint(JSON.stringify(backupControlBasis(backup)));
}

function backupCountComparisonRows(backupCounts, currentCounts, language) {
  const labels = {
    customers: language === "sv" ? "Kunder" : "Customers",
    invoices: language === "sv" ? "Fakturor" : "Invoices",
    journalEntries: language === "sv" ? "Bokforingsrader" : "Journal rows",
    auditEvents: language === "sv" ? "Handelser" : "Events"
  };

  return Object.keys(labels).map((key) => {
    const backupCount = Number(backupCounts?.[key] || 0);
    const currentCount = Number(currentCounts?.[key] || 0);
    return {
      key,
      label: labels[key],
      backupCount,
      currentCount,
      difference: backupCount - currentCount,
      matches: backupCount === currentCount
    };
  });
}

class RootAppErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      errorMessage: "",
      errorStack: "",
      componentStack: ""
    };
  }

  static getDerivedStateFromError(error) {
    return {
      hasError: true,
      errorMessage: error?.message || String(error || "Unknown render error"),
      errorStack: error?.stack || ""
    };
  }

  componentDidCatch(error, info) {
    console.error("AliBooks failed to render", error, info);
    this.setState({ componentStack: info?.componentStack || "" });

    try {
      const diagnostic = {
        message: error?.message || String(error || "Unknown render error"),
        stack: error?.stack || "",
        componentStack: info?.componentStack || "",
        at: new Date().toISOString()
      };
      sessionStorage.setItem("alibooks-last-render-error", JSON.stringify(diagnostic).slice(0, 12000));

      const recoveryKey = "alibooks-render-recovery-attempted";
      if (localStorage.getItem(recoveryKey) !== "true") {
        localStorage.setItem(recoveryKey, "true");
        localStorage.setItem("alibooks-active-view", "overview");
        window.location.reload();
      }
    } catch {
      // If browser storage is blocked, show the fallback below.
    }
  }

  resetAppView() {
    try {
      localStorage.setItem("alibooks-active-view", "overview");
      localStorage.removeItem("alibooks-render-recovery-attempted");
    } catch {
      // Ignore storage errors; reload still gives the app a clean render attempt.
    }
    window.location.reload();
  }

  clearLocalUiState() {
    try {
      Object.keys(localStorage)
        .filter((key) => key.startsWith("alibooks-") && key !== "alibooks-token" && key !== "alibooks-email" && key !== "alibooks-language")
        .forEach((key) => localStorage.removeItem(key));
      localStorage.removeItem("alibooks-render-recovery-attempted");
    } catch {
      // Ignore storage errors; reload still gives the app a clean render attempt.
    }
    window.location.reload();
  }

  render() {
    if (!this.state.hasError) {
      return this.props.children;
    }

    return (
      <main className="app-crash-fallback">
        <section>
          <p className="eyebrow">AliBooks</p>
          <h1>AliBooks kunde inte visa sidan</h1>
          <p>
            En sparad vy eller lokal UI-installning verkar ha kraschat renderingen. Appen har forsokt ga tillbaka till Oversikt automatiskt.
          </p>
          <div className="button-row">
            <button type="button" className="primary-small-button" onClick={() => this.resetAppView()}>
              Ga till Oversikt
            </button>
            <button type="button" className="secondary-button" onClick={() => this.clearLocalUiState()}>
              Rensa lokal UI-data
            </button>
          </div>
          <details className="app-crash-details" open>
            <summary>Teknisk felinformation</summary>
            <code>{this.state.errorMessage || "Inget felmeddelande hittades."}</code>
            <pre>
              {[this.state.errorStack, this.state.componentStack].filter(Boolean).join("\n\n") || "Ingen stack trace hittades."}
            </pre>
          </details>
        </section>
      </main>
    );
  }
}

function formatDateTime(value) {
  if (!value) return "-";

  return new Date(value).toLocaleString("sv-SE", {
    dateStyle: "short",
    timeStyle: "short"
  });
}

function formatDateOnly(value) {
  if (!value) return "-";

  return new Date(value).toLocaleDateString("sv-SE");
}

function formatMonthLabel(monthKey, language) {
  if (!monthKey) return "-";

  const date = new Date(`${monthKey}-01T12:00:00`);

  return date.toLocaleDateString(language === "sv" ? "sv-SE" : "en-GB", {
    year: "numeric",
    month: "long"
  });
}

function dateInputString(date) {
  const localDate = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return localDate.toISOString().slice(0, 10);
}

function lastDayOfMonth(monthValue) {
  const [year, month] = String(monthValue || "").split("-").map((part) => Number(part));
  if (!year || !month) return "";

  return new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10);
}

function addDaysInputString(value, days) {
  const date = value ? new Date(`${value}T12:00:00`) : new Date();
  date.setDate(date.getDate() + days);
  return dateInputString(date);
}

function addMonthsInputString(value, months, dayOfMonth = null) {
  const date = value ? new Date(`${value}T12:00:00`) : new Date();
  date.setMonth(date.getMonth() + months);

  if (dayOfMonth) {
    date.setDate(dayOfMonth);
  }

  return dateInputString(date);
}

function daysUntilInputDate(value, todayValue) {
  if (!value) return null;

  const target = new Date(`${value}T12:00:00`);
  const today = new Date(`${todayValue}T12:00:00`);
  return Math.ceil((target.getTime() - today.getTime()) / 86400000);
}

function currentMonthRange() {
  const now = new Date();
  return {
    from: dateInputString(new Date(now.getFullYear(), now.getMonth(), 1)),
    to: dateInputString(new Date(now.getFullYear(), now.getMonth() + 1, 0))
  };
}

function monthRangeFromKey(monthKey) {
  const [year, month] = String(monthKey || "").split("-").map(Number);

  if (!year || !month) {
    return { from: "", to: "" };
  }

  return {
    from: dateInputString(new Date(year, month - 1, 1)),
    to: dateInputString(new Date(year, month, 0))
  };
}


function currentQuarterRange() {
  const now = new Date();
  const quarterStartMonth = Math.floor(now.getMonth() / 3) * 3;
  return {
    from: dateInputString(new Date(now.getFullYear(), quarterStartMonth, 1)),
    to: dateInputString(new Date(now.getFullYear(), quarterStartMonth + 3, 0))
  };
}

function currentYearRange() {
  const now = new Date();
  return {
    from: dateInputString(new Date(now.getFullYear(), 0, 1)),
    to: dateInputString(new Date(now.getFullYear(), 11, 31))
  };
}

function currentFiscalYearRange(startMonth = 1, endMonth = 12) {
  const now = new Date();
  const startIndex = Math.max(1, Math.min(Number(startMonth || 1), 12)) - 1;
  const endIndex = Math.max(1, Math.min(Number(endMonth || 12), 12)) - 1;
  const startYear = now.getMonth() < startIndex ? now.getFullYear() - 1 : now.getFullYear();
  const endYear = startYear + (endIndex < startIndex ? 1 : 0);

  return {
    from: dateInputString(new Date(startYear, startIndex, 1)),
    to: dateInputString(new Date(endYear, endIndex + 1, 0))
  };
}

function currentVatReportingRange(vatReportingPeriod = "QUARTERLY", fiscalYearStartMonth = 1, fiscalYearEndMonth = 12) {
  if (vatReportingPeriod === "MONTHLY") return currentMonthRange();
  if (vatReportingPeriod === "YEARLY") return currentFiscalYearRange(fiscalYearStartMonth, fiscalYearEndMonth);
  return currentQuarterRange();
}

function selectedVatPeriodKind(from, to) {
  if (!from || !to) return "missing";

  const start = new Date(`${from}T12:00:00`);
  const end = new Date(`${to}T12:00:00`);

  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start > end) return "invalid";
  if (start.getDate() !== 1) return "custom";

  const expectedEnd = new Date(end.getFullYear(), end.getMonth() + 1, 0);
  if (end.getDate() !== expectedEnd.getDate()) return "custom";

  const monthCount = ((end.getFullYear() - start.getFullYear()) * 12) + end.getMonth() - start.getMonth() + 1;
  if (monthCount === 1) return "MONTHLY";
  if (monthCount === 3 && start.getMonth() % 3 === 0) return "QUARTERLY";
  if (monthCount === 12) return "YEARLY";
  return "custom";
}

function vatDeadlineForPeriod(periodEnd, vatReportingPeriod = "QUARTERLY") {
  if (!periodEnd) return "";

  const end = new Date(`${periodEnd}T12:00:00`);
  if (Number.isNaN(end.getTime())) return "";

  if (vatReportingPeriod === "YEARLY") {
    return dateInputString(new Date(end.getFullYear() + 1, 4, 12));
  }

  const targetMonth = end.getMonth() + 2;
  const targetYear = end.getFullYear() + Math.floor(targetMonth / 12);
  const normalizedMonth = targetMonth % 12;
  const day = normalizedMonth === 0 || normalizedMonth === 7 ? 17 : 12;
  return dateInputString(new Date(targetYear, normalizedMonth, day));
}

