  useEffect(() => {
    if (localStorage.getItem("alibooks-session-expired") !== "1") {
      return;
    }

    localStorage.removeItem("alibooks-session-expired");
    setError(language === "sv"
      ? "Din session har gatt ut. Logga in igen for att fortsatta."
      : "Your session has expired. Sign in again to continue.");
  }, [language]);

  useEffect(() => {
    if (!token) {
      return undefined;
    }

    if (jwtIsExpired(token)) {
      handleSessionExpired();
      return undefined;
    }

    const timer = window.setInterval(() => {
      if (jwtIsExpired(token)) {
        handleSessionExpired();
      }
    }, 30000);

    return () => window.clearInterval(timer);
  }, [token, language]);

  useEffect(() => {
    if (token && activeView === "vat") {
      loadVatReport();
      loadVatControlReport();
      loadVatVoucherControlReport();
      loadVatFilingProofReport();
      loadVatFilings();
    }
  }, [token, activeView, vatPeriodFrom, vatPeriodTo]);

  function authHeaders(authToken = token) {
    return {
      Authorization: `Bearer ${authToken}`
    };
  }

  function isAccountingDateLocked(date) {
    return Boolean(accountingLockedThroughDate && date && date <= accountingLockedThroughDate);
  }

  function lockedAccountingMessage(date) {
    const formattedDate = formatDateOnly(accountingLockedThroughDate || date);
    const sourceText = accountingLockSource === "vat"
      ? (language === "sv"
        ? " Lasket kommer fran en deklarerad eller betald momsperiod."
        : " The lock comes from a submitted or paid VAT period.")
      : "";
    return language === "sv"
      ? `Perioden ar last till och med ${formattedDate}. Valj ett senare datum.${sourceText}`
      : `The period is locked through ${formattedDate}. Choose a later date.${sourceText}`;
  }

  function selectedReportQuery(includeFrom = true) {
    const query = new URLSearchParams();
    if (includeFrom && vatPeriodFrom) query.set("from", vatPeriodFrom);
    if (vatPeriodTo) query.set("to", vatPeriodTo);
    return query.toString() ? `?${query.toString()}` : "";
  }

  function selectedBookkeepingQuery(accountNumber = "") {
    const query = new URLSearchParams();
    if (bookkeepingDateFrom) query.set("from", bookkeepingDateFrom);
    if (bookkeepingDateTo) query.set("to", bookkeepingDateTo);
    if (accountNumber) query.set("accountNumber", accountNumber);
    return query.toString() ? `?${query.toString()}` : "";
  }

  function shortIntegrityHash(value) {
    if (!value) return "-";
    const text = String(value);
    return text.length > 24 ? `${text.slice(0, 12)}...${text.slice(-8)}` : text;
  }

  async function loadServices() {
    try {
      const response = await fetch(`${apiUrl}/services`);
      const data = await response.json();
      if (!response.ok || !Array.isArray(data)) {
        setServices([]);
        setError(apiErrorMessage(data, "Could not load services."));
        return;
      }
      setServices(data);
      setSelectedServiceId((current) => {
        if (data.some((service) => String(service.id) === String(current))) {
          return current;
        }

        return String(data[0]?.id || "");
      });
    } catch {
      setError("Could not load services.");
    }
  }

