  async function createVatFiling(status = "DRAFT") {
    setError("");
    setVatFilingMessage("");

    if (!vatPeriodFrom || !vatPeriodTo) {
      setError(language === "sv" ? "Valj momsperiod fran och till forst." : "Choose VAT period from and to first.");
      return;
    }

    if (status === "PAID") {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(vatFilingPaymentDate)) {
        setError(language === "sv" ? "Betalningsdatum maste vara YYYY-MM-DD." : "Payment date must be YYYY-MM-DD.");
        return;
      }
      if (isAccountingDateLocked(vatFilingPaymentDate)) {
        setError(lockedAccountingMessage(vatFilingPaymentDate));
        return;
      }
    }

    const response = await fetch(`${apiUrl}/vat-filings`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        periodFrom: vatPeriodFrom,
        periodTo: vatPeriodTo,
        status,
        submissionReference: vatFilingSubmissionReference,
        paymentReference: vatFilingPaymentReference,
        paymentDate: vatFilingPaymentDate || null,
        note: vatFilingNote
      })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv"
        ? "Kunde inte arkivera momsdeklarationen."
        : "Could not archive VAT filing."));
      return;
    }

    setVatFilings((current) => [data, ...current.filter((item) => item.id !== data.id)]);
    loadJournalEntries();
    loadVatReport();
    loadBalanceReport();
    loadVatFilingProofReport();
    setVatFilingMessage(language === "sv"
      ? `Momsperioden sparades som ${vatFilingStatusLabel(data.status, language).toLowerCase()}.`
      : `VAT period saved as ${vatFilingStatusLabel(data.status, language).toLowerCase()}.`);
    loadAuditEvents();
  }

  async function updateVatFilingStatus(id, status) {
    setError("");
    setVatFilingMessage("");

    if (status === "PAID") {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(vatFilingPaymentDate)) {
        setError(language === "sv" ? "Betalningsdatum maste vara YYYY-MM-DD." : "Payment date must be YYYY-MM-DD.");
        return;
      }
      if (isAccountingDateLocked(vatFilingPaymentDate)) {
        setError(lockedAccountingMessage(vatFilingPaymentDate));
        return;
      }
    }

    const response = await fetch(`${apiUrl}/vat-filings/${id}/status`, {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        status,
        submissionReference: vatFilingSubmissionReference || selectedVatFiling?.submissionReference || "",
        paymentReference: vatFilingPaymentReference || selectedVatFiling?.paymentReference || "",
        paymentDate: vatFilingPaymentDate || null,
        note: vatFilingNote || selectedVatFiling?.note || ""
      })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv"
        ? "Kunde inte uppdatera momsstatus."
        : "Could not update VAT filing status."));
      return;
    }

    setVatFilings((current) => current.map((item) => item.id === data.id ? data : item));
    setVatFilingMessage(language === "sv"
      ? `Momsperioden ar nu ${vatFilingStatusLabel(data.status, language).toLowerCase()}.`
      : `VAT period is now ${vatFilingStatusLabel(data.status, language).toLowerCase()}.`);
    loadJournalEntries();
    loadVatReport();
    loadBalanceReport();
    loadVatFilingProofReport();
    loadAuditEvents();
  }

  async function createVatSettlementVoucher() {
    setError("");

    if (!vatPeriodFrom || !vatPeriodTo) {
      setError(language === "sv" ? "Valj momsperiod fran och till forst." : "Choose VAT period from and to first.");
      return;
    }

    if (vatFilingBlockedByVatControl) {
      setError(language === "sv"
        ? "Ratta kritiska moms- och verifikationsproblem innan du bokfor momsavstamning."
        : "Fix critical VAT and voucher issues before booking VAT settlement.");
      return;
    }

    const confirmed = window.confirm(language === "sv"
      ? `Vill du skapa momsavstamningsverifikat for ${vatPeriodFrom} - ${vatPeriodTo}?`
      : `Create VAT settlement voucher for ${vatPeriodFrom} - ${vatPeriodTo}?`);

    if (!confirmed) return;

    const response = await fetch(`${apiUrl}/vat-report/settlement`, {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        periodFrom: vatPeriodFrom,
        periodTo: vatPeriodTo,
        settlementDate: vatPeriodTo
      })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv"
        ? "Kunde inte skapa momsavstamningsverifikat."
        : "Could not create VAT settlement voucher."));
      return;
    }

    loadJournalEntries();
    loadVatReport();
    loadVatControlReport();
    loadVatVoucherControlReport();
    loadVatFilingProofReport();
    loadVatFilings();
    loadAuditEvents();
    setActiveView("bookkeeping");
    setBookkeepingSearch(Array.isArray(data) && data[0]?.voucherNumber ? data[0].voucherNumber : "MOMS");
  }

