  function supplierInvoiceStatusLabel(status) {
    if (status === "paid") return language === "sv" ? "Betald" : "Paid";
    if (status === "partial") return language === "sv" ? "Delbetald" : "Partly paid";
    if (status === "prepared") return language === "sv" ? "Forberedd" : "Prepared";
    if (status === "booked") return language === "sv" ? "Bokford som kostnad" : "Booked as expense";
    if (status === "cancelled") return language === "sv" ? "Makulerad" : "Cancelled";
    return language === "sv" ? "Obetald" : "Unpaid";
  }

  function supplierInvoiceNetAmount(invoice) {
    return Math.max(0, Number(invoice.totalAmount || 0) - Number(invoice.vatAmount || 0));
  }

  function supplierInvoicePaidAmount(invoice) {
    return Math.max(0, Number(invoice.paidAmount || 0));
  }

  function supplierInvoiceRemainingAmount(invoice) {
    return Math.max(Number(invoice.totalAmount || 0) - supplierInvoicePaidAmount(invoice), 0);
  }

  function supplierInvoiceIsOpenPayable(invoice) {
    const status = invoice.status || "unpaid";
    return supplierInvoiceRemainingAmount(invoice) > 0 && !["paid", "cancelled"].includes(status);
  }

  async function handleCreateSupplier(event) {
    event.preventDefault();
    setSupplierMessage("");
    setError("");

    const normalizedName = supplierName.trim();
    if (normalizedName.length < 2) {
      setSupplierMessage(language === "sv" ? "Skriv leverantorens namn." : "Enter supplier name.");
      return;
    }

    const supplierPayload = {
      name: normalizedName,
      email: supplierEmail.trim(),
      orgNumber: supplierOrgNumber.trim(),
      phone: supplierPhone.trim(),
      paymentInfo: supplierPaymentInfo.trim()
    };

    if (token) {
      const response = await fetch(`${apiUrl}/suppliers`, {
        method: "POST",
        headers: {
          ...authHeaders(),
          "Content-Type": "application/json"
        },
        body: JSON.stringify(supplierPayload)
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setSupplierMessage(apiErrorMessage(data, language === "sv" ? "Kunde inte spara leverantoren." : "Could not save supplier."));
        return;
      }

      setSuppliers((current) => [data, ...current.filter((supplier) => String(supplier.id) !== String(data.id))]);
      setSupplierInvoiceSupplierId(String(data.id));
      setSupplierName("");
      setSupplierEmail("");
      setSupplierOrgNumber("");
      setSupplierPhone("");
      setSupplierPaymentInfo("");
      setSupplierMessage(language === "sv" ? "Leverantoren sparades i databasen." : "Supplier saved in the database.");
      return;
    }

    const newSupplier = {
      id: `supplier-${Date.now()}`,
      ...supplierPayload,
      createdAt: new Date().toISOString()
    };

    setSuppliers((current) => [newSupplier, ...current]);
    setSupplierInvoiceSupplierId(newSupplier.id);
    setSupplierName("");
    setSupplierEmail("");
    setSupplierOrgNumber("");
    setSupplierPhone("");
    setSupplierPaymentInfo("");
    setSupplierMessage(language === "sv" ? "Leverantoren sparades." : "Supplier saved.");
  }

  async function handleCreateSupplierInvoice(event) {
    event.preventDefault();
    setSupplierMessage("");
    setError("");

    const supplier = suppliers.find((item) => String(item.id) === String(supplierInvoiceSupplierId));
    const totalAmount = Math.round(Number(supplierInvoiceTotalAmount || 0));
    const vatAmount = Math.round(Number(supplierInvoiceVatAmount || 0));

    if (!supplier) {
      setSupplierMessage(language === "sv" ? "Valj leverantor." : "Choose supplier.");
      return;
    }

    if (!supplierInvoiceDescription.trim()) {
      setSupplierMessage(language === "sv" ? "Skriv vad inkopet galler." : "Enter what the purchase is for.");
      return;
    }

    if (!supplierInvoiceDate || !supplierInvoiceDueDate) {
      setSupplierMessage(language === "sv" ? "Valj fakturadatum och forfallodatum." : "Choose invoice date and due date.");
      return;
    }

    if (supplierInvoiceDueDate < supplierInvoiceDate) {
      setSupplierMessage(language === "sv" ? "Forfallodatum kan inte vara fore fakturadatum." : "Due date cannot be before invoice date.");
      return;
    }

    if (totalAmount <= 0 || vatAmount < 0 || vatAmount > totalAmount) {
      setSupplierMessage(language === "sv" ? "Kontrollera totalbelopp och moms." : "Check total amount and VAT.");
      return;
    }

    if (supplierInvoiceSelfBilling && supplierInvoiceBuyerName.trim().length < 2) {
      setSupplierMessage(language === "sv" ? "Skriv koparens namn for sjalvfakturan." : "Enter the buyer name for the self-billing invoice.");
      return;
    }

    if (supplierInvoiceSelfBilling && supplierInvoiceApprovalReference.trim().length < 3) {
      setSupplierMessage(language === "sv" ? "Skriv avtal eller godkannandereferens for sjalvfakturan." : "Enter an agreement or approval reference for the self-billing invoice.");
      return;
    }

    const invoicePayload = {
      supplierId: supplier.id,
      invoiceDate: supplierInvoiceDate,
      dueDate: supplierInvoiceDueDate,
      description: supplierInvoiceDescription.trim(),
      reference: supplierInvoiceReference.trim(),
      totalAmount,
      vatAmount,
      category: supplierInvoiceCategory,
      selfBilling: supplierInvoiceSelfBilling,
      buyerName: supplierInvoiceSelfBilling ? supplierInvoiceBuyerName.trim() : "",
      buyerReference: supplierInvoiceSelfBilling ? supplierInvoiceBuyerReference.trim() : "",
      approvalReference: supplierInvoiceSelfBilling ? supplierInvoiceApprovalReference.trim() : ""
    };

    if (token) {
      const response = await fetch(`${apiUrl}/supplier-invoices`, {
        method: "POST",
        headers: {
          ...authHeaders(),
          "Content-Type": "application/json"
        },
        body: JSON.stringify(invoicePayload)
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setSupplierMessage(apiErrorMessage(data, language === "sv" ? "Kunde inte spara leverantorsfakturan." : "Could not save supplier invoice."));
        return;
      }

      setSupplierInvoices((current) => [data, ...current.filter((invoice) => String(invoice.id) !== String(data.id))]);
      setSupplierInvoiceDescription("");
      setSupplierInvoiceReference("");
      setSupplierInvoiceTotalAmount("");
      setSupplierInvoiceVatAmount("");
      setSupplierInvoiceSelfBilling(false);
      setSupplierInvoiceBuyerName("");
      setSupplierInvoiceBuyerReference("");
      setSupplierInvoiceApprovalReference("");
      setSupplierMessage(settings?.accountingMethod === "CASH_METHOD"
        ? (language === "sv"
          ? "Leverantorsfakturan sparades. Med kontantmetoden bokfors kostnad och moms nar du markerar den som betald."
          : "Supplier invoice saved. With cash method, expense and VAT are booked when you mark it as paid.")
        : (language === "sv"
          ? "Leverantorsfakturan sparades och bokfordes mot 2440."
          : "Supplier invoice saved and booked against 2440."));
      return;
    }

    const newInvoice = {
      id: `supplier-invoice-${Date.now()}`,
      ...invoicePayload,
      supplierName: supplier.name,
      supplierEmail: supplier.email,
      supplierOrgNumber: supplier.orgNumber,
      netAmount: Math.max(0, totalAmount - vatAmount),
      paidAmount: 0,
      paymentReference: "",
      paymentHistory: "",
      selfBilling: supplierInvoiceSelfBilling,
      buyerName: supplierInvoiceSelfBilling ? supplierInvoiceBuyerName.trim() : "",
      buyerReference: supplierInvoiceSelfBilling ? supplierInvoiceBuyerReference.trim() : "",
      approvalReference: supplierInvoiceSelfBilling ? supplierInvoiceApprovalReference.trim() : "",
      status: "unpaid",
      createdAt: new Date().toISOString()
    };

    setSupplierInvoices((current) => [newInvoice, ...current]);
    setSupplierInvoiceDescription("");
    setSupplierInvoiceReference("");
    setSupplierInvoiceTotalAmount("");
    setSupplierInvoiceVatAmount("");
    setSupplierInvoiceSelfBilling(false);
    setSupplierInvoiceBuyerName("");
    setSupplierInvoiceBuyerReference("");
    setSupplierInvoiceApprovalReference("");
    setSupplierMessage(language === "sv" ? "Leverantorsfakturan sparades." : "Supplier invoice saved.");
  }

  async function updateSupplierInvoiceStatus(invoiceId, status, paidAmountOverride = null, paymentReferenceOverride = "") {
    const currentInvoice = supplierInvoices.find((invoice) => String(invoice.id) === String(invoiceId));
    const remainingAmount = currentInvoice ? supplierInvoiceRemainingAmount(currentInvoice) : 0;
    const paidAmount = status === "paid"
      ? Math.round(Number(paidAmountOverride || supplierPaymentAmounts[invoiceId] || remainingAmount))
      : 0;
    const paymentReference = paymentReferenceOverride || supplierPaymentReferences[invoiceId] || "";

    if (status !== "paid" && currentInvoice && (["paid", "partial", "booked"].includes(currentInvoice.status) || supplierInvoicePaidAmount(currentInvoice) > 0)) {
      setSupplierMessage(language === "sv"
        ? "Leverantorsfakturan har redan betalning eller bokforingshistorik. Skapa rattelse eller korrigerande post i stallet for att backa status."
        : "The supplier invoice already has payment or bookkeeping history. Create a correction or adjusting entry instead of moving the status backwards.");
      return;
    }

    if (status === "paid" && paidAmount <= 0) {
      setSupplierMessage(language === "sv" ? "Skriv ett betalbelopp som ar storre an 0." : "Enter a payment amount greater than 0.");
      return;
    }

    if (status === "paid" && paidAmount > remainingAmount) {
      setSupplierMessage(language === "sv" ? "Betalbeloppet kan inte vara storre an kvar att betala." : "Payment amount cannot be greater than remaining amount.");
      return;
    }

    if (token && !String(invoiceId).startsWith("supplier-invoice-")) {
      const response = await fetch(`${apiUrl}/supplier-invoices/${invoiceId}/status`, {
        method: "PATCH",
        headers: {
          ...authHeaders(),
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          status,
          paidAt: status === "paid" ? dateInputString(new Date()) : null,
          paidAmount: status === "paid" ? paidAmount : null,
          paymentReference: status === "paid" ? paymentReference : ""
        })
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setSupplierMessage(apiErrorMessage(data, language === "sv" ? "Kunde inte uppdatera status." : "Could not update status."));
        return;
      }

      setSupplierInvoices((current) => current.map((invoice) => (
        String(invoice.id) === String(invoiceId) ? data : invoice
      )));
      if (status === "paid") {
        setSupplierPaymentAmounts((current) => ({ ...current, [invoiceId]: "" }));
        setSupplierPaymentReferences((current) => ({ ...current, [invoiceId]: "" }));
        const supplierPaymentBookingText = settings?.accountingMethod === "CASH_METHOD"
          ? (language === "sv" ? "kostnad, moms och bank enligt kontantmetoden" : "expense, VAT and bank using cash method")
          : "2440/1930";
        setSupplierMessage(data.status === "paid"
          ? (language === "sv"
            ? `Leverantorsfakturan ar fullbetald och bokford mot ${supplierPaymentBookingText}.`
            : `Supplier invoice is fully paid and booked against ${supplierPaymentBookingText}.`)
          : (language === "sv"
            ? `Delbetalning pa ${paidAmount} SEK bokfordes mot ${supplierPaymentBookingText}.`
            : `Partial payment of ${paidAmount} SEK booked against ${supplierPaymentBookingText}.`));
      } else if (status === "booked") {
        setSupplierMessage(settings?.accountingMethod === "CASH_METHOD"
          ? (language === "sv"
            ? "Kontantmetoden ar vald: kostnad och moms bokfors nar leverantorsfakturan betalas."
            : "Cash method is selected: expense and VAT are booked when the supplier invoice is paid.")
          : (language === "sv" ? "Leverantorsfakturan ar bokford mot 2440." : "Supplier invoice is booked against 2440."));
      }
      return;
    }

    setSupplierInvoices((current) => current.map((invoice) => (
      invoice.id === invoiceId
        ? status === "paid"
          ? (() => {
            const nextPaidAmount = Math.min(Number(invoice.totalAmount || 0), supplierInvoicePaidAmount(invoice) + paidAmount);
            const paymentDate = dateInputString(new Date());
            const historyLine = `${paymentDate} - ${paidAmount} SEK${paymentReference ? ` - ${paymentReference}` : ""}`;
            return {
              ...invoice,
              paidAmount: nextPaidAmount,
              paymentReference,
              paymentHistory: invoice.paymentHistory ? `${invoice.paymentHistory}\n${historyLine}` : historyLine,
              status: nextPaidAmount >= Number(invoice.totalAmount || 0) ? "paid" : "partial",
              paidAt: paymentDate,
              updatedAt: new Date().toISOString()
            };
          })()
          : {
            ...invoice,
            status,
            updatedAt: new Date().toISOString()
          }
        : invoice
    )));
    if (status === "paid") {
      setSupplierPaymentAmounts((current) => ({ ...current, [invoiceId]: "" }));
      setSupplierPaymentReferences((current) => ({ ...current, [invoiceId]: "" }));
      setSupplierMessage(language === "sv" ? `Betalning pa ${paidAmount} SEK registrerades.` : `Payment of ${paidAmount} SEK registered.`);
    }
  }

  async function cancelSupplierInvoice(invoice) {
    if (!invoice) return;

    if (["paid", "partial"].includes(invoice.status) || supplierInvoicePaidAmount(invoice) > 0) {
      setSupplierMessage(language === "sv"
        ? "Leverantorsfakturan har betalning. Skapa en betalningsrattelse innan den makuleras."
        : "The supplier invoice has payments. Create a payment correction before cancelling it.");
      return;
    }

    if (!window.confirm(language === "sv"
      ? "Makulera leverantorsfakturan och skapa rattelseverifikat som vander bokforingen?"
      : "Cancel the supplier invoice and create a correction voucher reversing the bookkeeping?")) {
      return;
    }

    if (token && !String(invoice.id).startsWith("supplier-invoice-")) {
      const response = await fetch(`${apiUrl}/supplier-invoices/${invoice.id}/cancel`, {
        method: "POST",
        headers: {
          ...authHeaders(),
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ cancellationDate: dateInputString(new Date()) })
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setSupplierMessage(apiErrorMessage(data, language === "sv"
          ? "Kunde inte makulera leverantorsfakturan."
          : "Could not cancel supplier invoice."));
        return;
      }

      setSupplierInvoices((current) => current.map((currentInvoice) => (
        String(currentInvoice.id) === String(invoice.id) ? data : currentInvoice
      )));
      await loadJournalEntries();
      loadProfitAndLoss();
      loadBalanceReport();
      setSupplierMessage(language === "sv"
        ? `Leverantorsfakturan makulerades${data.cancellationVoucherNumber ? ` med rattelseverifikat ${data.cancellationVoucherNumber}` : ""}.`
        : `Supplier invoice cancelled${data.cancellationVoucherNumber ? ` with correction voucher ${data.cancellationVoucherNumber}` : ""}.`);
      return;
    }

    setSupplierInvoices((current) => current.map((currentInvoice) => (
      String(currentInvoice.id) === String(invoice.id)
        ? { ...currentInvoice, status: "cancelled", cancelledAt: dateInputString(new Date()), cancellationVoucherNumber: "", updatedAt: new Date().toISOString() }
        : currentInvoice
    )));
    setSupplierMessage(language === "sv" ? "Leverantorsfakturan makulerades lokalt." : "Supplier invoice cancelled locally.");
  }

