  function openServiceJobDailySchedule() {
    const selectedRows = serviceJobRows.filter((job) => job.date === serviceJobDate);
    const reportWindow = window.open("", "_blank", "noopener,noreferrer");

    if (!reportWindow) {
      setServiceJobMessage(language === "sv" ? "Webblasaren blockerade dagsschemat." : "The browser blocked the daily schedule.");
      return;
    }

    const rows = selectedRows.length > 0
      ? selectedRows.map((job) => `<tr>
          <td>${escapeHtml(`${job.startTime || ""}-${job.endTime || ""}`)}</td>
          <td>${escapeHtml(job.customerName || "-")}</td>
          <td>${escapeHtml(job.serviceName || "-")}</td>
          <td>${escapeHtml(job.address || "-")}</td>
          <td>${escapeHtml(serviceJobStatusLabel(job.status))}</td>
          <td>${escapeHtml(job.notes || "")}</td>
        </tr>`).join("")
      : `<tr><td colspan="6">${language === "sv" ? "Inga jobb pa valt datum." : "No jobs on selected date."}</td></tr>`;

    reportWindow.document.write(`<!doctype html>
<html lang="${language === "sv" ? "sv" : "en"}">
<head>
  <meta charset="utf-8" />
  <title>${language === "sv" ? "Dagsschema" : "Daily schedule"} - ${escapeHtml(serviceJobDate)}</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 32px; color: #17202a; }
    header { border-bottom: 4px solid #1f62ff; padding-bottom: 18px; }
    h1 { margin: 0 0 8px; }
    .brand { color: #1f62ff; font-weight: 800; font-size: 30px; }
    .accent { color: #d6a700; font-weight: 800; }
    table { width: 100%; border-collapse: collapse; margin-top: 22px; }
    th, td { border-bottom: 1px solid #d9e2ec; padding: 10px; text-align: left; vertical-align: top; }
    th { background: #f4f7fb; }
    @media print { button { display: none; } body { margin: 18px; } }
  </style>
</head>
<body>
  <header>
    <div class="brand">AliBooks</div>
    <div class="accent">${escapeHtml(settings?.companySubtitle || "Muscle&Focus")}</div>
    <h1>${language === "sv" ? "Dagsschema" : "Daily schedule"} ${escapeHtml(serviceJobDate)}</h1>
  </header>
  <table>
    <thead>
      <tr>
        <th>${language === "sv" ? "Tid" : "Time"}</th>
        <th>${language === "sv" ? "Kund" : "Customer"}</th>
        <th>${language === "sv" ? "Tjanst" : "Service"}</th>
        <th>${language === "sv" ? "Adress" : "Address"}</th>
        <th>Status</th>
        <th>${language === "sv" ? "Notering" : "Note"}</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  <p>${language === "sv" ? "Antal jobb" : "Jobs"}: ${selectedRows.length}</p>
  <button onclick="window.print()">${language === "sv" ? "Skriv ut / spara PDF" : "Print / save PDF"}</button>
</body>
</html>`);
    reportWindow.document.close();
  }

  function downloadServiceJobScheduleCsv() {
    const rows = [
      ["Dagsschema / Daily schedule"],
      ["Valt datum", serviceJobDate],
      ["Antal", serviceJobScheduleDateRows.length],
      [],
      ["Datum", "Tid", "Status", "Kund", "Personnummer", "Telefon", "Tjanst", "Adress", "Totalt", "RUT/ROT", "Kund betalar", "Schemakrock", "Notering"]
    ];

    serviceJobRows.forEach((job) => {
      const customer = customers.find((item) => String(item.id) === String(job.customerId)) || {};
      rows.push([
        job.date,
        `${job.startTime || ""}-${job.endTime || ""}`,
        serviceJobStatusLabel(job.status),
        job.customerName,
        job.customerPersonalNumber,
        customer.phone || "",
        job.serviceName,
        job.address,
        job.calculation.totalAmount,
        job.calculation.rutRotAmount,
        job.calculation.customerPays,
        serviceJobConflictIds.has(job.id) ? "Ja" : "Nej",
        job.notes || ""
      ]);
    });

    downloadLocalCsv("servicejobb-dagsschema.csv", rows);
  }

