  async function saveSettingsChanges(updatedSettings, successMessage = t.settingsSaved) {
    setError("");
    setSettingsMessage("");

    const response = await fetch(`${apiUrl}/settings`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify(updatedSettings)
    });

    const data = await response.json();

    if (!response.ok) {
      setError(apiErrorMessage(data, "Could not save settings."));
      return null;
    }

    setSettings(data);
    setSettingsMessage(successMessage);
    loadAccounts();
    loadBalanceReport();
    return data;
  }

  async function handleSaveSettings(event) {
    event.preventDefault();
    await saveSettingsChanges(settings);
  }

  async function closeSelectedAccountingPeriod() {
    setPeriodCloseMessage("");

    if (!settings) {
      setError(language === "sv" ? "Installningar ar inte laddade annu." : "Settings are not loaded yet.");
      return;
    }

    if (!vatPeriodTo) {
      setError(language === "sv" ? "Valj ett slutdatum for perioden forst." : "Choose an end date for the period first.");
      return;
    }

    if (accountingLockedThroughDate && accountingLockedThroughDate >= vatPeriodTo) {
      setPeriodCloseMessage(language === "sv"
        ? `Perioden ar redan last till ${formatDateOnly(accountingLockedThroughDate)}.`
        : `The period is already locked through ${formatDateOnly(accountingLockedThroughDate)}.`);
      return;
    }

    if (selectedPeriodProfessionalLockBlockers.length > 0 || selectedPeriodProfessionalLockWarnings.length > 0) {
      setPeriodCloseMessage(language === "sv"
        ? "Perioden kan inte lasas annu. Atgarda kontrollpunkterna i listan forst."
        : "The period cannot be locked yet. Resolve the control points in the list first.");
      return;
    }

    const confirmed = window.confirm(language === "sv"
      ? `Vill du lasa bokforingen till och med ${formatDateOnly(vatPeriodTo)}? Efter detta ska andringar i perioden goras som korrigeringar i en nyare period.`
      : `Lock bookkeeping through ${formatDateOnly(vatPeriodTo)}? After this, changes in the period should be made as corrections in a later period.`);

    if (!confirmed) return;

    const response = await fetch(`${apiUrl}/accounting-period/close`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({ lockedThroughDate: vatPeriodTo })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setPeriodCloseMessage(apiErrorMessage(data, language === "sv"
        ? "Perioden kunde inte lasas. Kontrollera verifikat, fakturautkast och underlag."
        : "The period could not be locked. Check vouchers, draft invoices and evidence."));
      return;
    }

    const successMessage = language === "sv"
      ? `Perioden ar last till ${formatDateOnly(data.lockedThroughDate || vatPeriodTo)}.`
      : `Period locked through ${formatDateOnly(data.lockedThroughDate || vatPeriodTo)}.`;
    await loadSettings();
    loadAuditEvents();
    setPeriodCloseMessage(successMessage);
  }

  async function loadBackendPeriodCloseCheck({ silent = false } = {}) {
    if (!token || !vatPeriodTo) {
      return null;
    }

    if (!silent) {
      setBackendPeriodCloseCheckMessage("");
    }
    setBackendPeriodCloseCheckLoading(true);

    const query = new URLSearchParams();
    query.set("lockedThroughDate", vatPeriodTo);

    try {
      const response = await fetch(`${apiUrl}/accounting-period/close-check?${query.toString()}`, {
        headers: authHeaders()
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        const message = apiErrorMessage(data, language === "sv"
          ? "Kunde inte hamta backendens periodkontroll."
          : "Could not load backend period control.");
        if (!silent) {
          setBackendPeriodCloseCheckMessage(message);
        }
        setBackendPeriodCloseCheck(null);
        return null;
      }

      setBackendPeriodCloseCheck(data);
      if (!silent) {
        setBackendPeriodCloseCheckMessage(language === "sv"
          ? "Backendens periodkontroll uppdaterades."
          : "Backend period control updated.");
      }
      return data;
    } catch {
      if (!silent) {
        setBackendPeriodCloseCheckMessage(language === "sv"
          ? "Kunde inte na backendens periodkontroll. Kontrollera att Spring Boot ar igang."
          : "Could not reach backend period control. Check that Spring Boot is running.");
      }
      setBackendPeriodCloseCheck(null);
      return null;
    } finally {
      setBackendPeriodCloseCheckLoading(false);
    }
  }

