  async function updateInvoiceStatus(id, status, paymentOverride = {}) {
    setError("");
    const isPaid = status.toLowerCase() === "paid";
    const paymentDate = paymentOverride.paymentDate || paymentDates[id] || new Date().toISOString().slice(0, 10);
    const invoiceToPay = invoices.find((item) => item.id === id);
    const remainingAmount = invoiceRemainingAmount(invoiceToPay || {});
    const paidAmount = Number(paymentOverride.paidAmount ?? paymentAmounts[id] ?? remainingAmount);
    const paymentReference = paymentOverride.paymentReference || paymentReferences[id] || "";

    if (status.toLowerCase() === "sent" && invoiceToPay && !invoiceCanBeMarkedSent(invoiceToPay)) {
      setError(language === "sv" ? "Den fakturan kan inte markeras som skickad i sin nuvarande status." : "This invoice cannot be marked as sent in its current status.");
      return;
    }

    if (isPaid && invoiceToPay && !invoiceCanReceivePayment(invoiceToPay)) {
      setError(language === "sv" ? "Den fakturan kan inte ta emot vanlig betalning. Anvand kreditfaktura eller aterbetalning vid behov." : "This invoice cannot receive a normal payment. Use credit invoice or refund when needed.");
      return;
    }

    if (isPaid && !/^\d{4}-\d{2}-\d{2}$/.test(paymentDate)) {
      setError(language === "sv" ? "Betalningsdatum maste vara YYYY-MM-DD." : "Payment date must be YYYY-MM-DD.");
      return;
    }

    if (isPaid && isAccountingDateLocked(paymentDate)) {
      setError(lockedAccountingMessage(paymentDate));
      return;
    }

    if (isPaid && invoiceToPay?.invoiceDate && paymentDate < invoiceToPay.invoiceDate) {
      setError(language === "sv" ? "Betalningsdatum kan inte vara fore fakturadatum." : "Payment date cannot be before invoice date.");
      return;
    }

    if (isPaid && (!Number.isSafeInteger(paidAmount) || paidAmount <= 0)) {
      setError(language === "sv" ? "Ange ett positivt betalningsbelopp i hela kronor." : "Enter a positive payment amount in whole SEK.");
      return;
    }

    if (isPaid && paidAmount > remainingAmount) {
      setError(language === "sv" ? "Betalt belopp kan inte vara storre an kvar att betala." : "Paid amount cannot be greater than remaining amount.");
      return;
    }

    const response = await fetch(`${apiUrl}/invoices/${id}/${status.toLowerCase()}`, {
      method: "POST",
      headers: {
        ...(isPaid ? { "Content-Type": "application/json" } : {}),
        Authorization: `Bearer ${token}`
      },
      body: isPaid ? JSON.stringify({ paymentDate, paidAmount, paymentReference }) : undefined
    });

    const data = await response.json();

    if (!response.ok) {
      setError(apiErrorMessage(data, "Could not update invoice."));
      return;
    }

    setInvoices((current) => current.map((item) => (item.id === id ? data : item)));
    loadJournalEntries();
    loadVatReport();
    loadReminders();
    loadAdvisorSummary();
    loadProfitAndLoss();
    loadBalanceReport();
  }

  async function registerInvoiceRefund(item) {
    setError("");
    const id = item?.id;
    const refundableAmount = invoiceRefundableAmount(item || {});
    const refundDate = refundDates[id] || new Date().toISOString().slice(0, 10);
    const refundAmount = Number(refundAmounts[id] ?? refundableAmount);
    const refundReference = refundReferences[id] || "";

    if (!id) {
      return;
    }

    if (!/^\d{4}-\d{2}-\d{2}$/.test(refundDate)) {
      setError(language === "sv" ? "Aterbetalningsdatum maste vara YYYY-MM-DD." : "Refund date must be YYYY-MM-DD.");
      return;
    }

    if (isAccountingDateLocked(refundDate)) {
      setError(lockedAccountingMessage(refundDate));
      return;
    }

    if (item.invoiceDate && refundDate < item.invoiceDate) {
      setError(language === "sv" ? "Aterbetalningsdatum kan inte vara fore fakturadatum." : "Refund date cannot be before invoice date.");
      return;
    }

    if (!Number.isSafeInteger(refundAmount) || refundAmount <= 0) {
      setError(language === "sv" ? "Ange ett positivt aterbetalningsbelopp i hela kronor." : "Enter a positive refund amount in whole SEK.");
      return;
    }

    if (refundAmount > refundableAmount) {
      setError(language === "sv" ? "Aterbetalningsbelopp kan inte vara storre an kvar att aterbetala." : "Refund amount cannot be greater than refundable amount.");
      return;
    }

    const response = await fetch(`${apiUrl}/invoices/${id}/refund`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ refundDate, refundAmount, refundReference })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte registrera aterbetalning." : "Could not register refund."));
      return;
    }

    setInvoices((current) => current.map((invoiceItem) => (invoiceItem.id === id ? data : invoiceItem)));
    loadJournalEntries();
    loadVatReport();
    loadAdvisorSummary();
    loadProfitAndLoss();
    loadBalanceReport();
  }

  async function createStripePayout() {
    setError("");
    setStripePayoutMessage("");

    const grossAmount = Number(stripePayoutGrossAmount);
    const feeAmount = Number(stripePayoutFeeAmount || 0);

    if (!/^\d{4}-\d{2}-\d{2}$/.test(stripePayoutDate)) {
      setError(language === "sv" ? "Utbetalningsdatum maste vara YYYY-MM-DD." : "Payout date must be YYYY-MM-DD.");
      return;
    }

    if (isAccountingDateLocked(stripePayoutDate)) {
      setError(lockedAccountingMessage(stripePayoutDate));
      return;
    }

    if (!Number.isFinite(grossAmount) || grossAmount <= 0) {
      setError(language === "sv" ? "Bruttobelopp fran Stripe maste vara storre an 0." : "Stripe gross amount must be greater than 0.");
      return;
    }

    if (!Number.isFinite(feeAmount) || feeAmount < 0) {
      setError(language === "sv" ? "Stripe-avgift kan inte vara negativ." : "Stripe fee cannot be negative.");
      return;
    }

    if (feeAmount > grossAmount) {
      setError(language === "sv" ? "Stripe-avgift kan inte vara storre an bruttobeloppet." : "Stripe fee cannot be greater than the gross amount.");
      return;
    }

    const response = await fetch(`${apiUrl}/journal-entries/stripe-payout`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({
        payoutDate: stripePayoutDate,
        grossAmount,
        feeAmount,
        reference: stripePayoutReference
      })
    });
    const data = await response.json();

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte bokfora Stripe-utbetalning." : "Could not book Stripe payout."));
      return;
    }

    setStripePayoutMessage(
      language === "sv"
        ? `Stripe-utbetalning bokford: ${grossAmount - feeAmount} SEK till bank och ${feeAmount} SEK avgift.`
        : `Stripe payout booked: ${grossAmount - feeAmount} SEK to bank and ${feeAmount} SEK fee.`
    );
    setStripePayoutGrossAmount("");
    setStripePayoutFeeAmount("");
    setStripePayoutReference("");
    loadJournalEntries();
    loadVatReport();
    loadProfitAndLoss();
    loadBalanceReport();
  }

