  async function deleteInvoice(item) {
    setError("");
    const id = item?.id;

    if (!id) return;

    if (item.status !== "DRAFT") {
      setError(language === "sv"
        ? "Bara fakturautkast kan tas bort. Skickade, betalda eller bokforda fakturor ska krediteras eller rattas."
        : "Only draft invoices can be deleted. Sent, paid or booked invoices should be credited or corrected.");
      return;
    }

    const confirmed = window.confirm(
      language === "sv"
        ? "Ta bort fakturautkastet? Detta ska bara anvandas innan fakturan har skickats."
        : "Delete this draft invoice? This should only be used before the invoice has been sent."
    );

    if (!confirmed) {
      return;
    }

    const response = await fetch(`${apiUrl}/invoices/${id}`, {
      method: "DELETE",
      headers: authHeaders()
    });

    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      setError(apiErrorMessage(data, "Could not delete invoice."));
      return;
    }

    setInvoices((current) => current.filter((item) => item.id !== id));
    loadJournalEntries();
    loadVatReport();
    loadReminders();
    loadAdvisorSummary();
    loadProfitAndLoss();
    loadBalanceReport();
  }

  async function createCreditInvoice(invoiceItem) {
    setError("");
    const id = typeof invoiceItem === "object" ? invoiceItem?.id : invoiceItem;

    if (!id) {
      return;
    }

    const hasPayment = typeof invoiceItem === "object" && invoiceHasRegisteredPayment(invoiceItem);
    const number = typeof invoiceItem === "object" ? invoiceNumber(invoiceItem) : "";
    const confirmed = window.confirm(language === "sv"
      ? [
          `Skapa kreditfaktura${number ? ` for ${number}` : ""}?`,
          "Originalfakturan behalls som historik och en kreditfaktura skapas for att vanda forsaljning och moms.",
          hasPayment ? "Fakturan har betalning registrerad. Om kunden ska fa pengar tillbaka behover aterbetalningen bokforas separat mot bank, Swish eller Stripe." : ""
        ].filter(Boolean).join("\n\n")
      : [
          `Create credit invoice${number ? ` for ${number}` : ""}?`,
          "The original invoice stays as history and a credit invoice is created to reverse revenue and VAT.",
          hasPayment ? "This invoice has registered payments. If the customer should receive money back, book the refund separately against bank, Swish or Stripe." : ""
        ].filter(Boolean).join("\n\n"));

    if (!confirmed) {
      return;
    }

    const response = await fetch(`${apiUrl}/invoices/${id}/credit`, {
      method: "POST",
      headers: authHeaders()
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      setError(apiErrorMessage(data, "Could not create credit invoice."));
      return;
    }

    loadInvoices();
    loadJournalEntries();
    loadVatReport();
    loadReminders();
    loadAdvisorSummary();
    loadProfitAndLoss();
    loadBalanceReport();
    setInvoiceSearch(invoiceNumber(data));
  }

