  function operationsReleaseStatusLabel(status) {
    if (status === "deployed") return language === "sv" ? "Deployad" : "Deployed";
    if (status === "failed") return language === "sv" ? "Misslyckad" : "Failed";
    if (status === "rolledBack") return language === "sv" ? "Tillbakarullad" : "Rolled back";
    return language === "sv" ? "Planerad" : "Planned";
  }

  function operationsReleaseEnvironmentLabel(environment) {
    if (environment === "production") return language === "sv" ? "Produktion" : "Production";
    if (environment === "staging") return "Staging";
    if (environment === "demo") return "Demo";
    return language === "sv" ? "Lokal" : "Local";
  }

  function handleCreateOperationsRelease(event) {
    event.preventDefault();
    setOperationsReleaseMessage("");
    setError("");

    if (!operationsReleaseVersion.trim()) {
      setOperationsReleaseMessage(language === "sv" ? "Skriv version eller release-namn." : "Enter a version or release name.");
      return;
    }

    if (!operationsReleaseRollbackPlan.trim()) {
      setOperationsReleaseMessage(language === "sv" ? "Skriv rollback-plan innan release sparas." : "Enter a rollback plan before saving the release.");
      return;
    }

    const release = {
      id: `release-${Date.now()}`,
      date: operationsReleaseDate || dateInputString(new Date()),
      version: operationsReleaseVersion.trim(),
      commit: operationsReleaseCommit.trim(),
      environment: operationsReleaseEnvironment,
      backupChecked: operationsReleaseBackupChecked,
      smokeTested: operationsReleaseSmokeTested,
      rollbackPlan: operationsReleaseRollbackPlan.trim(),
      notes: operationsReleaseNotes.trim(),
      status: operationsReleaseBackupChecked && operationsReleaseSmokeTested ? "deployed" : "planned",
      owner: currentEmail || "AliBooks",
      createdAt: new Date().toISOString(),
      deployedAt: operationsReleaseBackupChecked && operationsReleaseSmokeTested ? new Date().toISOString() : ""
    };

    setOperationsReleases((current) => [release, ...current]);
    setOperationsReleaseDate(dateInputString(new Date()));
    setOperationsReleaseVersion("");
    setOperationsReleaseCommit("");
    setOperationsReleaseEnvironment("local");
    setOperationsReleaseBackupChecked(false);
    setOperationsReleaseSmokeTested(false);
    setOperationsReleaseRollbackPlan("");
    setOperationsReleaseNotes("");
    setOperationsReleaseMessage(language === "sv" ? "Release sparades i driftjournalen." : "Release saved to the operations journal.");
  }

  function updateOperationsReleaseStatus(releaseId, status) {
    setOperationsReleases((current) => current.map((release) => (
      release.id === releaseId
        ? {
            ...release,
            status,
            deployedAt: status === "deployed" ? new Date().toISOString() : release.deployedAt || "",
            updatedAt: new Date().toISOString()
          }
        : release
    )));
  }

  function deleteOperationsRelease(releaseId) {
    setOperationsReleases((current) => current.filter((release) => release.id !== releaseId));
  }

