  function voucherReviewStatusLabel(status) {
    if (status === "approved") return language === "sv" ? "Godkand" : "Approved";
    if (status === "blocked") return language === "sv" ? "Blockerad" : "Blocked";
    return language === "sv" ? "Granska" : "Review";
  }

  async function loadVoucherApprovals(authToken = token) {
    if (!authToken) return;

    try {
      const response = await fetch(`${apiUrl}/voucher-approvals`, {
        headers: authHeaders(authToken)
      });
      const data = await response.json().catch(() => []);

      if (!response.ok || !Array.isArray(data)) {
        return;
      }

      const decisions = data.reduce((summary, approval) => {
        if (!approval.voucherNumber) return summary;
        summary[approval.voucherNumber] = {
          status: approval.status || "pending",
          note: approval.note || "",
          reviewedAt: approval.reviewedAt || approval.updatedAt || "",
          reviewer: approval.reviewer || ""
        };
        return summary;
      }, {});
      setVoucherReviewDecisions((current) => ({
        ...current,
        ...decisions
      }));
    } catch {
      // Keep local decisions as offline fallback.
    }
  }

  async function updateVoucherReviewDecision(voucherNumber, status) {
    const cleanVoucherNumber = String(voucherNumber || "").trim();
    if (!cleanVoucherNumber) return;

    const nextDecision = {
        status,
        note: voucherReviewComment.trim(),
        reviewedAt: new Date().toISOString(),
        reviewer: currentEmail || email || "AliBooks"
    };
    setVoucherReviewDecisions((current) => ({
      ...current,
      [cleanVoucherNumber]: nextDecision
    }));
    setVoucherReviewComment("");

    if (!token) return;

    try {
      const response = await fetch(`${apiUrl}/voucher-approvals/${encodeURIComponent(cleanVoucherNumber)}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders()
        },
        body: JSON.stringify({
          status,
          note: nextDecision.note,
          reviewer: nextDecision.reviewer
        })
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setError(apiErrorMessage(data, language === "sv" ? "Kunde inte spara attestbeslut." : "Could not save approval decision."));
        return;
      }

      setVoucherReviewDecisions((current) => ({
        ...current,
        [cleanVoucherNumber]: {
          status: data.status || status,
          note: data.note || "",
          reviewedAt: data.reviewedAt || data.updatedAt || nextDecision.reviewedAt,
          reviewer: data.reviewer || nextDecision.reviewer
        }
      }));
      loadAuditEvents();
    } catch {
      setError(language === "sv" ? "Kunde inte kontakta backend for attestbeslut." : "Could not contact backend for approval decision.");
    }
  }

  async function clearVoucherReviewDecision(voucherNumber) {
    const cleanVoucherNumber = String(voucherNumber || "").trim();
    if (!cleanVoucherNumber) return;

    setVoucherReviewDecisions((current) => {
      const next = { ...current };
      delete next[cleanVoucherNumber];
      return next;
    });

    if (!token) return;

    try {
      const response = await fetch(`${apiUrl}/voucher-approvals/${encodeURIComponent(cleanVoucherNumber)}`, {
        method: "DELETE",
        headers: authHeaders()
      });

      if (!response.ok) {
        const data = await response.json().catch(() => ({}));
        setError(apiErrorMessage(data, language === "sv" ? "Kunde inte nollstalla attestbeslut." : "Could not reset approval decision."));
        return;
      }

      loadAuditEvents();
    } catch {
      setError(language === "sv" ? "Kunde inte kontakta backend for nollstallning." : "Could not contact backend for reset.");
    }
  }

