  function openPayrollYearReport() {
    const reportWindow = window.open("", "_blank", "noopener,noreferrer");

    if (!reportWindow) {
      setError(language === "sv" ? "Webblasaren blockerade arsrapporten." : "The browser blocked the yearly payroll report.");
      return;
    }

    const reportTitle = language === "sv" ? "Arsrapport lon" : "Payroll yearly report";
    const companyName = settings?.companyName || "Muscle&Focus";
    const companyEmail = settings?.contactEmail || currentEmail || "ali.wafa17943@gmail.com";
    const rowsHtml = payrollYearRows.length > 0
      ? payrollYearRows.map((row) => `<tr>
          <td>${escapeHtml(row.employeeName)}</td>
          <td>${escapeHtml(row.personalNumber || "-")}</td>
          <td>${escapeHtml(row.months.join(", ") || "-")}</td>
          <td>${row.gross} SEK</td>
          <td>${row.tax} SEK</td>
          <td>${row.net} SEK</td>
          <td>${row.employerFees} SEK</td>
          <td>${row.totalCost} SEK</td>
          <td>${escapeHtml(row.statusLabel)}</td>
        </tr>`).join("")
      : `<tr><td colspan="9">${language === "sv" ? "Inga loner for aret." : "No payroll for this year."}</td></tr>`;

    reportWindow.document.write(`<!doctype html>
<html lang="${language === "sv" ? "sv" : "en"}">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(reportTitle)} - ${escapeHtml(payrollReportYear || "-")}</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 0; color: #172033; background: #f6f8fc; }
    main { max-width: 1060px; margin: 32px auto; background: #fff; border: 1px solid #dce5f2; border-radius: 14px; padding: 34px; }
    header { display: flex; justify-content: space-between; gap: 24px; border-bottom: 4px solid #1d5cff; padding-bottom: 22px; }
    h1 { margin: 0; color: #1d5cff; font-size: 34px; }
    h2 { margin-top: 28px; font-size: 18px; }
    p { margin: 5px 0; }
    .muted { color: #516174; }
    .summary { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; margin: 22px 0; }
    .summary div { border: 1px solid #dce5f2; border-radius: 10px; padding: 14px; background: #f9fbff; }
    .summary span { display: block; color: #516174; font-weight: 700; }
    .summary strong { display: block; margin-top: 6px; font-size: 19px; }
    table { width: 100%; border-collapse: collapse; margin-top: 14px; }
    th, td { border-bottom: 1px solid #dce5f2; padding: 10px 8px; text-align: left; }
    th:nth-child(n+4), td:nth-child(n+4) { text-align: right; }
    th:last-child, td:last-child { text-align: left; }
    .note { margin-top: 18px; padding: 14px; border: 1px solid #f1d28a; border-radius: 10px; background: #fff8e5; }
    .actions { margin-top: 24px; }
    button { background: #1d5cff; color: white; border: 0; border-radius: 8px; padding: 12px 18px; font-weight: 700; cursor: pointer; }
    @media print {
      body { background: #fff; }
      main { margin: 0; border: 0; border-radius: 0; }
      .actions { display: none; }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <div>
        <h1>${escapeHtml(reportTitle)}</h1>
        <p class="muted">${escapeHtml(companyName)}</p>
        <p class="muted">${escapeHtml(companyEmail)}</p>
      </div>
      <div>
        <p><strong>${language === "sv" ? "Ar" : "Year"}:</strong> ${escapeHtml(payrollReportYear || "-")}</p>
        <p><strong>${language === "sv" ? "Loner" : "Payroll rows"}:</strong> ${payrollYearTotals.count}</p>
        <p><strong>${language === "sv" ? "Bokforda" : "Booked"}:</strong> ${payrollYearTotals.booked}/${payrollYearTotals.count}</p>
      </div>
    </header>

    <section class="summary">
      <div><span>${language === "sv" ? "Bruttolon" : "Gross salary"}</span><strong>${payrollYearTotals.gross} SEK</strong></div>
      <div><span>${language === "sv" ? "Preliminar skatt" : "Preliminary tax"}</span><strong>${payrollYearTotals.tax} SEK</strong></div>
      <div><span>${language === "sv" ? "Nettolon" : "Net pay"}</span><strong>${payrollYearTotals.net} SEK</strong></div>
      <div><span>${language === "sv" ? "Arbetsgivaravgift" : "Employer contribution"}</span><strong>${payrollYearTotals.employerFees} SEK</strong></div>
      <div><span>${language === "sv" ? "Total kostnad" : "Total cost"}</span><strong>${payrollYearTotals.totalCost} SEK</strong></div>
    </section>

    <h2>${language === "sv" ? "Per anstalld" : "Per employee"}</h2>
    <table>
      <thead>
        <tr>
          <th>${language === "sv" ? "Anstalld" : "Employee"}</th>
          <th>${language === "sv" ? "Personnummer" : "Personal number"}</th>
          <th>${language === "sv" ? "Manader" : "Months"}</th>
          <th>${language === "sv" ? "Brutto" : "Gross"}</th>
          <th>${language === "sv" ? "Skatt" : "Tax"}</th>
          <th>${language === "sv" ? "Netto" : "Net"}</th>
          <th>${language === "sv" ? "Avgift" : "Contribution"}</th>
          <th>${language === "sv" ? "Total" : "Total"}</th>
          <th>${language === "sv" ? "Status" : "Status"}</th>
        </tr>
      </thead>
      <tbody>${rowsHtml}</tbody>
    </table>

    <div class="note">${language === "sv"
      ? "Anvand arsrapporten som kontrollunderlag. Kontrollera alltid exakta individuppgifter, skattetabeller och arbetsgivardeklarationer mot Skatteverket."
      : "Use the yearly report as a control basis. Always verify exact employee details, tax tables and employer declarations with the tax authority."}</div>
    <div class="actions"><button onclick="window.print()">${language === "sv" ? "Skriv ut / spara PDF" : "Print / save PDF"}</button></div>
  </main>
</body>
</html>`);
    reportWindow.document.close();
  }

  function downloadPayrollPaymentCsv() {
    setError("");
    const rows = [
      ["Lonebetalningslista / Payroll payment list"],
      ["Period", payrollReportMonth || "-"],
      ["Nettolon att betala", payrollPaymentTotals.netToPay],
      ["Nettolon betald", payrollPaymentTotals.netPaid],
      ["Kvar att betala", payrollPaymentTotals.netRemaining],
      ["Skatt att reservera", payrollPaymentTotals.taxToReserve],
      ["Avgifter att reservera", payrollPaymentTotals.employerFeesToReserve],
      ["Skatt/avgifter reserverade", payrollPaymentTotals.reservedCount],
      [],
      ["Anstalld", "Personnummer", "Clearingnummer", "Kontonummer", "Nettolon", "Preliminar skatt", "Arbetsgivaravgift", "Nettolon betald", "Skatt/avgift reserverad", "Status"]
    ];

    payrollPaymentRows.forEach((row) => {
      rows.push([
        row.employeeName,
        row.personalNumber || "",
        row.clearingNumber || "",
        row.bankAccount || "",
        row.netPay,
        row.withheldTax,
        row.employerFee,
        row.netPaid ? "Ja" : "Nej",
        row.taxReserved ? "Ja" : "Nej",
        row.statusLabel
      ]);
    });

    downloadLocalCsv(`lonebetalningar-${payrollReportMonth || "period"}.csv`, rows);
  }

  function downloadPayrollBankPaymentCsv() {
    setError("");

    if (!payrollSalaryPaymentDate) {
      setError(language === "sv" ? "Valj utbetalningsdatum for lon." : "Choose salary payment date.");
      return;
    }

    const rows = [
      ["Loneutbetalning bankunderlag / Payroll bank payment basis"],
      ["Period", payrollReportMonth || "-"],
      ["Utbetalningsdatum", payrollSalaryPaymentDate],
      ["Nettolon att betala", payrollPaymentTotals.netToPay],
      ["Saknar bankkonto", payrollPaymentTotals.missingBankAccounts],
      [],
      ["Betalningsdatum", "Mottagare", "Personnummer", "Clearingnummer", "Kontonummer", "Belopp", "Valuta", "Referens", "Status"]
    ];

    payrollPaymentRows.forEach((row) => {
      rows.push([
        payrollSalaryPaymentDate,
        row.employeeName,
        row.personalNumber || "",
        row.clearingNumber || "",
        row.bankAccount || "",
        row.netPay,
        "SEK",
        `Lon ${row.period} ${row.employeeName}`,
        row.clearingNumber && row.bankAccount ? "Klar" : "Saknar bankkonto"
      ]);
    });

    const batch = {
      id: Date.now(),
      period: payrollReportMonth || "",
      paymentDate: payrollSalaryPaymentDate,
      createdAt: new Date().toISOString(),
      totalAmount: payrollPaymentTotals.netToPay,
      count: payrollPaymentRows.length,
      missingBankAccounts: payrollPaymentTotals.missingBankAccounts,
      rows: payrollPaymentRows.map((row) => ({
        draftId: row.id,
        employeeName: row.employeeName,
        personalNumber: row.personalNumber || "",
        clearingNumber: row.clearingNumber || "",
        bankAccount: row.bankAccount || "",
        amount: row.netPay,
        reference: `Lon ${row.period} ${row.employeeName}`
      }))
    };

    setPayrollPaymentBatches((current) => [batch, ...current].slice(0, 20));
    downloadLocalCsv(`lone-bankunderlag-${payrollReportMonth || "period"}.csv`, rows);
    setPayrollMessage(language === "sv"
      ? `Bankfil skapad for ${batch.count} loner, totalt ${batch.totalAmount} SEK.`
      : `Bank file created for ${batch.count} payroll payments, total ${batch.totalAmount} SEK.`);
  }

  function markPayrollPaymentBatchPaid(batch) {
    setError("");

    if (!batch?.rows?.length) {
      setError(language === "sv" ? "Batchen saknar betalningsrader." : "The batch has no payment rows.");
      return;
    }

    setPayrollPaymentStatuses((current) => {
      const next = { ...current };
      batch.rows.forEach((row) => {
        next[row.draftId] = {
          ...(next[row.draftId] || {}),
          netPaid: true,
          netPaidAt: batch.paymentDate,
          paymentBatchId: batch.id,
          paymentReference: `Bankfil ${batch.period}`,
          updatedAt: new Date().toISOString()
        };
      });
      return next;
    });

    setPayrollPaymentBatches((current) => current.map((item) => (
      item.id === batch.id
        ? { ...item, status: "paid", markedPaidAt: new Date().toISOString() }
        : item
    )));
    setPayrollMessage(language === "sv"
      ? `Batch ${formatDateOnly(batch.paymentDate)} markerades som betald.`
      : `Batch ${formatDateOnly(batch.paymentDate)} was marked as paid.`);
  }

  function updatePayrollTaxSettlement(field, value) {
    setPayrollTaxSettlements((current) => ({
      ...current,
      [payrollReportMonth]: {
        ...(current[payrollReportMonth] || {}),
        [field]: value,
        updatedAt: new Date().toISOString()
      }
    }));
  }

  async function bookPayrollTaxAccountTransfer() {
    setError("");
    const amount = payrollPaymentTotals.taxToReserve + payrollPaymentTotals.employerFeesToReserve;

    if (amount <= 0) {
      setError(language === "sv" ? "Det finns ingen skatt eller arbetsgivaravgift att bokfora for vald period." : "There is no tax or employer contribution to book for selected period.");
      return;
    }

    if (!payrollTaxPaymentDate) {
      setError(language === "sv" ? "Valj betalningsdatum for skattekonto." : "Choose tax account payment date.");
      return;
    }

    if (isAccountingDateLocked(payrollTaxPaymentDate)) {
      setError(lockedAccountingMessage(payrollTaxPaymentDate));
      return;
    }

    const response = await fetch(`${apiUrl}/journal-entries/manual-multi`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        voucherDate: payrollTaxPaymentDate,
        description: `Inbetalning skattekonto ${payrollReportMonth}`,
        lines: [
          { accountNumber: "1630", debit: amount, credit: 0 },
          { accountNumber: "1930", debit: 0, credit: amount }
        ]
      })
    });

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte bokfora inbetalning till skattekonto." : "Could not book tax account payment."));
      return;
    }

    const voucherNumber = data?.[0]?.voucherNumber || "";
    updatePayrollTaxSettlement("taxAccountTransferVoucher", voucherNumber || "booked");
    setPayrollMessage(language === "sv"
      ? `Inbetalning till skattekonto bokfordes${voucherNumber ? ` som ${voucherNumber}` : ""}.`
      : `Tax account payment was booked${voucherNumber ? ` as ${voucherNumber}` : ""}.`);
    loadJournalEntries();
    loadBalanceReport();
  }

  async function bookPayrollTaxSettlement() {
    setError("");
    const tax = payrollPaymentTotals.taxToReserve;
    const employerFees = payrollPaymentTotals.employerFeesToReserve;
    const amount = tax + employerFees;

    if (amount <= 0) {
      setError(language === "sv" ? "Det finns ingen skatt eller arbetsgivaravgift att avrakna for vald period." : "There is no tax or employer contribution to settle for selected period.");
      return;
    }

    if (!payrollTaxPaymentDate) {
      setError(language === "sv" ? "Valj datum for avrakningen." : "Choose settlement date.");
      return;
    }

    if (isAccountingDateLocked(payrollTaxPaymentDate)) {
      setError(lockedAccountingMessage(payrollTaxPaymentDate));
      return;
    }

    const response = await fetch(`${apiUrl}/journal-entries/manual-multi`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        voucherDate: payrollTaxPaymentDate,
        description: `Avrakning arbetsgivardeklaration ${payrollReportMonth}`,
        lines: [
          { accountNumber: "2710", debit: tax, credit: 0 },
          { accountNumber: "2731", debit: employerFees, credit: 0 },
          { accountNumber: "1630", debit: 0, credit: amount }
        ].filter((line) => line.debit > 0 || line.credit > 0)
      })
    });

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte bokfora avrakning mot skattekonto." : "Could not book tax account settlement."));
      return;
    }

    const voucherNumber = data?.[0]?.voucherNumber || "";
    updatePayrollTaxSettlement("taxSettlementVoucher", voucherNumber || "booked");
    setPayrollMessage(language === "sv"
      ? `Avrakning mot skattekonto bokfordes${voucherNumber ? ` som ${voucherNumber}` : ""}.`
      : `Tax account settlement was booked${voucherNumber ? ` as ${voucherNumber}` : ""}.`);
    loadJournalEntries();
    loadBalanceReport();
  }

  function payrollSnapshotPayload() {
    return {
      version: 1,
      savedAt: new Date().toISOString(),
      employees: payrollEmployees,
      drafts: payrollDrafts,
      paymentStatuses: payrollPaymentStatuses,
      paymentBatches: payrollPaymentBatches,
      payslipStatuses: payrollPayslipStatuses,
      taxSettlements: payrollTaxSettlements,
      reportMonth: payrollReportMonth,
      reportYear: payrollReportYear,
      salaryPaymentDate: payrollSalaryPaymentDate,
      taxPaymentDate: payrollTaxPaymentDate,
      taxRate: payrollTaxRate,
      employerRate: payrollEmployerRate,
      salaryAccount: payrollSalaryAccount,
      autoSyncEnabled: payrollAutoSyncEnabled,
      lastSyncedAt: payrollLastSyncedAt
    };
  }

  function applyPayrollSnapshot(snapshot) {
    setPayrollEmployees(Array.isArray(snapshot.employees) ? snapshot.employees : []);
    setPayrollDrafts(Array.isArray(snapshot.drafts) ? snapshot.drafts : []);
    setPayrollPaymentStatuses(snapshot.paymentStatuses && typeof snapshot.paymentStatuses === "object" ? snapshot.paymentStatuses : {});
    setPayrollPaymentBatches(Array.isArray(snapshot.paymentBatches) ? snapshot.paymentBatches : []);
    setPayrollPayslipStatuses(snapshot.payslipStatuses && typeof snapshot.payslipStatuses === "object" ? snapshot.payslipStatuses : {});
    setPayrollTaxSettlements(snapshot.taxSettlements && typeof snapshot.taxSettlements === "object" ? snapshot.taxSettlements : {});
    setPayrollReportMonth(snapshot.reportMonth || new Date().toISOString().slice(0, 7));
    setPayrollReportYear(snapshot.reportYear || new Date().toISOString().slice(0, 4));
    setPayrollSalaryPaymentDate(snapshot.salaryPaymentDate || new Date().toISOString().slice(0, 10));
    setPayrollTaxPaymentDate(snapshot.taxPaymentDate || new Date().toISOString().slice(0, 10));
    setPayrollTaxRate(String(snapshot.taxRate || "30"));
    setPayrollEmployerRate(String(snapshot.employerRate || "31.42"));
    setPayrollSalaryAccount(snapshot.salaryAccount || "7010");
    setPayrollSelectedEmployeeId("new");
    fillPayrollEmployeeForm(null);
  }

  async function loadPayrollSnapshotRevisions(options = {}) {
    const response = await fetch(`${apiUrl}/payroll/snapshot/revisions`, {
      headers: authHeaders()
    });

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      if (!options.silent) {
        setError(apiErrorMessage(data, language === "sv" ? "Kunde inte ladda lonehistorik." : "Could not load payroll history."));
      }
      return;
    }

    setPayrollSnapshotRevisions(Array.isArray(data) ? data : []);
  }

  async function savePayrollSnapshotToDatabase(options = {}) {
    setError("");

    const response = await fetch(`${apiUrl}/payroll/snapshot`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        content: JSON.stringify(payrollSnapshotPayload())
      })
    });

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      setPayrollSyncStatus(language === "sv" ? "Lonesynk misslyckades" : "Payroll sync failed");
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte spara lon i databasen." : "Could not save payroll to database."));
      return;
    }

    const syncedAt = data?.updatedAt || new Date().toISOString();
    setPayrollLastSyncedAt(syncedAt);
    setPayrollSyncStatus(language === "sv"
      ? `Synkad ${formatDateTime(syncedAt)}`
      : `Synced ${formatDateTime(syncedAt)}`);

    if (!options.silent) {
      setPayrollMessage(language === "sv"
        ? `Lon sparad i databasen${data?.updatedAt ? ` ${formatDateTime(data.updatedAt)}` : ""}.`
        : `Payroll saved to database${data?.updatedAt ? ` ${formatDateTime(data.updatedAt)}` : ""}.`);
    }
    loadPayrollSnapshotRevisions({ silent: true });
  }

  async function loadPayrollSnapshotFromDatabase(options = {}) {
    setError("");
    setPayrollSyncStatus(language === "sv" ? "Laddar lon fran databasen..." : "Loading payroll from database...");

    const response = await fetch(`${apiUrl}/payroll/snapshot`, {
      headers: authHeaders()
    });

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      setPayrollSnapshotReady(false);
      setPayrollSyncStatus(language === "sv" ? "Kunde inte ladda lonesynk" : "Could not load payroll sync");
      setError(apiErrorMessage(data, language === "sv" ? "Kunde inte ladda lon fran databasen." : "Could not load payroll from database."));
      return;
    }

    if (!data?.content) {
      setPayrollSnapshotReady(Boolean(options.markReady));
      setPayrollSyncStatus(language === "sv" ? "Ingen lon i databasen an" : "No payroll in database yet");
      loadPayrollSnapshotRevisions({ silent: true });
      if (!options.silent) {
        setPayrollMessage(language === "sv" ? "Ingen lon sparad i databasen annu." : "No payroll saved in database yet.");
      }
      return;
    }

    let snapshot;
    try {
      snapshot = JSON.parse(data.content);
    } catch {
      setPayrollSnapshotReady(false);
      setPayrollSyncStatus(language === "sv" ? "Sparad lonedata kunde inte lasas" : "Saved payroll data could not be read");
      setError(language === "sv" ? "Sparad lonedata kunde inte lasas." : "Saved payroll data could not be read.");
      return;
    }

    applyPayrollSnapshot(snapshot);
    setPayrollSnapshotReady(Boolean(options.markReady) || payrollSnapshotReady);
    setPayrollLastSyncedAt(data?.updatedAt || "");
    setPayrollSyncStatus(language === "sv"
      ? `Laddad ${data?.updatedAt ? formatDateTime(data.updatedAt) : ""}`.trim()
      : `Loaded ${data?.updatedAt ? formatDateTime(data.updatedAt) : ""}`.trim());
    loadPayrollSnapshotRevisions({ silent: true });
    if (!options.silent) {
      setPayrollMessage(language === "sv"
        ? `Lon laddad fran databasen${data?.updatedAt ? ` ${formatDateTime(data.updatedAt)}` : ""}.`
        : `Payroll loaded from database${data?.updatedAt ? ` ${formatDateTime(data.updatedAt)}` : ""}.`);
    }
  }

  function restorePayrollSnapshotRevision(revision) {
    setError("");

    let snapshot;
    try {
      snapshot = JSON.parse(revision.content || "");
    } catch {
      setError(language === "sv" ? "Versionen kunde inte lasas." : "The revision could not be read.");
      return;
    }

    applyPayrollSnapshot(snapshot);
    setPayrollSnapshotReady(true);
    setPayrollLastSyncedAt(revision.createdAt || "");
    setPayrollSyncStatus(language === "sv"
      ? `Aterstalld ${revision.createdAt ? formatDateTime(revision.createdAt) : ""}`.trim()
      : `Restored ${revision.createdAt ? formatDateTime(revision.createdAt) : ""}`.trim());
    setPayrollMessage(payrollAutoSyncEnabled
      ? (language === "sv"
        ? "Loneversion aterstalld. Autosynk sparar den som ny aktuell version."
        : "Payroll revision restored. Auto sync will save it as the new current version.")
      : (language === "sv"
        ? "Loneversion aterstalld. Klicka Spara DB om du vill gora den aktuell i databasen."
        : "Payroll revision restored. Click Save DB if you want to make it current in the database."));
  }

