  async function validateBackupFile(event) {
    setError("");
    setSettingsMessage("");
    const file = event.target.files?.[0];

    if (!file) return;

    try {
      const parsed = JSON.parse(await file.text());
      const issues = [];

      if (parsed.app !== "AliBooks") {
        issues.push(language === "sv" ? "Filen verkar inte vara en AliBooks-backup." : "The file does not look like an AliBooks backup.");
      }

      if (!parsed.version) {
        issues.push(language === "sv" ? "Backupversion saknas." : "Backup version is missing.");
      }

      if (!parsed.exportedAt) {
        issues.push(language === "sv" ? "Exportdatum saknas." : "Export date is missing.");
      }

      if (!Array.isArray(parsed.customers)) {
        issues.push(language === "sv" ? "Kundlista saknas eller ar fel format." : "Customer list is missing or has the wrong format.");
      }

      if (!Array.isArray(parsed.invoices)) {
        issues.push(language === "sv" ? "Fakturalista saknas eller ar fel format." : "Invoice list is missing or has the wrong format.");
      }

      if (!Array.isArray(parsed.journalEntries)) {
        issues.push(language === "sv" ? "Bokforingsrader saknas eller ar fel format." : "Journal entries are missing or have the wrong format.");
      }

      const summary = parsed.summary || {};
      const integrityProofs = parsed.integrityProofs || {};
      const auditProof = integrityProofs.auditTrail || {};
      const bookkeepingProof = integrityProofs.bookkeeping || {};
      const integrityManifest = parsed.integrityManifest || {};
      const backupPayloadForHash = { ...parsed };
      delete backupPayloadForHash.integrityManifest;
      const expectedPayloadSha256 = await sha256Hex(stableJsonForHash(backupPayloadForHash));
      const manifestForHash = { ...integrityManifest };
      delete manifestForHash.manifestSha256;
      const expectedManifestSha256 = Object.keys(integrityManifest).length > 0
        ? await sha256Hex(stableJsonForHash(manifestForHash))
        : "";
      const actualPayloadSha256 = integrityManifest.payloadSha256 || "";
      const actualManifestSha256 = integrityManifest.manifestSha256 || "";
      const expectedControlStamp = backupControlFingerprint(parsed);
      const actualControlStamp = parsed.controlStamp?.value || "";
      const backupAuditEventCount = Array.isArray(parsed.reports?.auditTrail) ? parsed.reports.auditTrail.length : summary.auditEvents || 0;
      const backupJournalEntryCount = Array.isArray(parsed.journalEntries) ? parsed.journalEntries.length : summary.journalEntries || 0;
      const backupCounts = {
        customers: Array.isArray(parsed.customers) ? parsed.customers.length : summary.customers || 0,
        invoices: Array.isArray(parsed.invoices) ? parsed.invoices.length : summary.invoices || 0,
        expenses: Array.isArray(parsed.expenses) ? parsed.expenses.length : summary.expenses || 0,
        journalEntries: backupJournalEntryCount,
        auditEvents: backupAuditEventCount
      };
      const currentCounts = {
        customers: customers.length,
        invoices: invoices.length,
        expenses: expenses.length,
        journalEntries: journalEntries.length,
        auditEvents: auditTrailRows.length
      };
      const countComparison = backupCountComparisonRows(backupCounts, currentCounts, language);
      const mismatchedCounts = countComparison.filter((row) => !row.matches);

      if (!actualControlStamp) {
        issues.push(language === "sv" ? "Backupen saknar kontrollstampel." : "The backup is missing a control stamp.");
      } else if (actualControlStamp !== expectedControlStamp) {
        issues.push(language === "sv" ? "Backupens kontrollstampel matchar inte innehållet." : "The backup control stamp does not match the content.");
      }

      if (!actualPayloadSha256 || !actualManifestSha256) {
        issues.push(language === "sv" ? "Backupen saknar SHA-256 manifest for filintegritet." : "The backup is missing a SHA-256 integrity manifest.");
      } else if (actualPayloadSha256 !== expectedPayloadSha256 || actualManifestSha256 !== expectedManifestSha256) {
        issues.push(language === "sv" ? "Backupens SHA-256 kontrollkod matchar inte filens innehall." : "The backup SHA-256 control code does not match the file content.");
      }

      if (!auditProof.auditFingerprint || !auditProof.finalChainHash) {
        issues.push(language === "sv" ? "Backupen saknar revisionssparets auditstampel eller slutliga kedjekod." : "The backup is missing the audit trail fingerprint or final chain hash.");
      }

      if ((summary.backendAuditEvents || backupAuditEventCount) > 0 && Number(auditProof.eventCount || 0) < Number(summary.backendAuditEvents || backupAuditEventCount || 0)) {
        issues.push(language === "sv" ? "Auditkedjans antal handelser matchar inte backupens revisionsspar." : "The audit chain event count does not match the backup audit trail.");
      }

      if (backupJournalEntryCount > 0 && (!bookkeepingProof.periodFingerprint || !bookkeepingProof.finalChainHash)) {
        issues.push(language === "sv" ? "Backupen saknar bokforingens periodstampel eller slutliga kedjekod." : "The backup is missing the bookkeeping period fingerprint or final chain hash.");
      }

      if (mismatchedCounts.length > 0) {
        issues.push(language === "sv"
          ? "Backupens antal matchar inte nuvarande appdata. Kontrollera att du verifierar senaste backupen."
          : "The backup counts do not match current app data. Check that you are verifying the latest backup.");
      }

      setBackupValidation({
        ok: issues.length === 0,
        fileName: file.name,
        exportedAt: parsed.exportedAt || "",
        version: parsed.version || "-",
        periodLabel: parsed.period?.label || "-",
        containsPersonalData: parsed.containsPersonalData !== false,
        issues,
        controlStamp: {
          ok: Boolean(actualControlStamp && actualControlStamp === expectedControlStamp),
          value: actualControlStamp,
          expected: expectedControlStamp,
          algorithm: parsed.controlStamp?.algorithm || "FNV1A-32"
        },
        integrityManifest: {
          ok: Boolean(actualPayloadSha256 && actualPayloadSha256 === expectedPayloadSha256 && actualManifestSha256 && actualManifestSha256 === expectedManifestSha256),
          payloadSha256: actualPayloadSha256,
          expectedPayloadSha256,
          manifestSha256: actualManifestSha256,
          expectedManifestSha256,
          algorithm: integrityManifest.algorithm || "SHA-256"
        },
        proofs: {
          audit: {
            ok: Boolean(auditProof.auditFingerprint && auditProof.finalChainHash),
            eventCount: Number(auditProof.eventCount || summary.auditIntegrityEvents || 0),
            fingerprint: auditProof.auditFingerprint || summary.auditFingerprint || "",
            finalChainHash: auditProof.finalChainHash || ""
          },
          bookkeeping: {
            ok: Boolean(bookkeepingProof.periodFingerprint && bookkeepingProof.finalChainHash),
            entryCount: Number(bookkeepingProof.entryCount || backupJournalEntryCount || 0),
            voucherCount: Number(bookkeepingProof.voucherCount || 0),
            periodFingerprint: bookkeepingProof.periodFingerprint || "",
            finalChainHash: bookkeepingProof.finalChainHash || ""
          }
        },
        counts: {
          ...backupCounts
        },
        currentCounts,
        countComparison,
        countComparisonOk: mismatchedCounts.length === 0
      });

      setSettingsMessage(issues.length === 0
        ? (language === "sv" ? "Backupfilen ser giltig ut. Ingen data har importerats." : "Backup file looks valid. No data has been imported.")
        : (language === "sv" ? "Backupfilen kunde lasas men har varningar." : "Backup file could be read but has warnings."));
    } catch {
      setBackupValidation({
        ok: false,
        fileName: file.name,
        exportedAt: "",
        version: "-",
        periodLabel: "-",
        containsPersonalData: true,
        issues: [language === "sv" ? "Filen kunde inte lasas som JSON." : "The file could not be read as JSON."],
        controlStamp: {
          ok: false,
          value: "",
          expected: "",
          algorithm: "FNV1A-32"
        },
        integrityManifest: {
          ok: false,
          payloadSha256: "",
          expectedPayloadSha256: "",
          manifestSha256: "",
          expectedManifestSha256: "",
          algorithm: "SHA-256"
        },
        proofs: {
          audit: {
            ok: false,
            eventCount: 0,
            fingerprint: "",
            finalChainHash: ""
          },
          bookkeeping: {
            ok: false,
            entryCount: 0,
            voucherCount: 0,
            periodFingerprint: "",
            finalChainHash: ""
          }
        },
        counts: {
          customers: 0,
          invoices: 0,
          expenses: 0,
          journalEntries: 0,
          auditEvents: 0
        },
        currentCounts: {
          customers: customers.length,
          invoices: invoices.length,
          expenses: expenses.length,
          journalEntries: journalEntries.length,
          auditEvents: auditTrailRows.length
        },
        countComparison: [],
        countComparisonOk: false
      });
    } finally {
      event.target.value = "";
    }
  }

