    if (isManual) reviewReasons.push(language === "sv" ? "Manuell bokforing" : "Manual bookkeeping");
    if (isCorrection) reviewReasons.push(language === "sv" ? `Rattelse av ${row.correctionOfVoucherNumber}` : `Correction of ${row.correctionOfVoucherNumber}`);
    if (isHighAmount) reviewReasons.push(language === "sv" ? "Hogt belopp" : "High amount");
    if (accountingLockedThroughDate && row.voucherDate && row.voucherDate <= accountingLockedThroughDate) {
      reviewReasons.push(language === "sv" ? "Ligger i last historik" : "Inside locked history");
    }

    const defaultStatus = row.status === "critical" ? "blocked" : "pending";
    const reviewStatus = decision.status || defaultStatus;
    const risk = row.status === "critical" || reviewStatus === "blocked"
      ? "critical"
      : reviewReasons.length > 0 || reviewStatus === "pending"
