      score: payablesOverdueRows.length > 0 ? 76 : supplierPayablesTotal > Math.max(cashOpeningBalance + totalOutstanding, 0) ? 82 : 100,
      amount: supplierPayablesTotal,
      detail: `${payablesOverdueRows.length} ${language === "sv" ? "forfallna, " : "overdue, "}${supplierInvoicesToBook.length} ${language === "sv" ? "redo att bokfora" : "ready to book"}`,
      recommendation: language === "sv"
        ? "Leverantorsskulder ska kunna stammas av mot fakturor och framtida bankbetalningar."
        : "Payables should reconcile to supplier invoices and future bank payments.",
