      priority: taxCenterCriticalCount > 0 ? 1 : taxCenterWarningCount > 0 || vatPeriodToPay > cashOpeningBalance ? 2 : 5,
      score: taxCenterCriticalCount > 0 ? 40 : taxCenterWarningCount > 0 || vatPeriodToPay > cashOpeningBalance ? 78 : 100,
      amount: vatPeriodToPay,
      detail: `${vatPeriodToPay} SEK ${language === "sv" ? "moms, reserv" : "VAT, reserve"} ${reservePlanTotal} SEK`,
      recommendation: language === "sv"
