      priority: accountingQualityCriticalCount > 0 ? 1 : accountingQualityWarningCount > 0 ? 2 : 5,
      score: accountingQualityScore,
      amount: accountingQualityCriticalCount,
      amountLabel: `${accountingQualityCriticalCount}`,
      detail: `${accountingQualityCriticalCount} ${language === "sv" ? "stoppar, " : "blocking, "}${accountingQualityWarningCount} ${language === "sv" ? "varningar" : "warnings"}`,
      recommendation: language === "sv"
        ? "Rensa stoppande punkter i Redovisningskontroll innan du litar pa resultat och balans."
        : "Clear blocking items in Accounting quality before trusting profit and balance.",
